mapper.select:
		/** [sql-anomaly.xml] AnomalyMapper.getSeq **/
		SELECT COALESCE(MAX(ST09_SEQ)+1,1) AS ST09_SEQ
          FROM TB_ST_09
          WHERE ST09_COMPANY = #{st09Company}
            AND ST09_FACTORY = #{st09Factory}
            AND TO_CHAR(ST09_DAT, 'YYYYMMDD') = TO_CHAR(SYSDATE, 'YYYYMMDD')

/** [sql-anomaly.xml] AnomalyMapper.getDuplicationAnomalyInfo **/
SELECT * 
FROM TB_ST_09
WHERE 1=1
AND ST09_COMPANY 	= #{st09Company}
AND ST09_FACTORY 	= #{st09Factory}
AND ST09_QRCODE 	= #{st09Qrcode}

mapper.insert:
    	/** [sql-anomaly.xml] AnomalyMapper.insertOfAnomaly **/
        INSERT INTO TB_ST_09
		(
			  ST09_COMPANY
			, ST09_FACTORY
			, ST09_NO
			, ST09_DAT
			, ST09_SEQ
			, ST09_GBN
			, ST09_CODE
			, ST09_UNT
			, ST09_LOT
			, ST09_RMK
			, ST09_LINE
			, ST09_QTY
			, ST09_LOT_SEQ
			, ST09_QRCODE
			, ST09_EQUIP_CODE
			, ST09_INDTE
			, ST09_EMPNO
			, ST09_DEPT
		)
		VALUES
		(
			  #{st09Company}
			, #{st09Factory}
			, CONCAT(TO_CHAR(SYSDATE, 'YYYYMMDD'), LPAD(#{st09Seq}, 5, '0'))
			, SYSDATE
			, #{st09Seq}
			, #{st09Gbn}
			, #{st09Code}
			, #{st09Unt}
			, #{st09Lot}
			, '[PDA]포장/실적 공정 이상관리'
			, #{st09Line}
			, 1
			, #{st09LotSeq}
			, #{st09Qrcode}
			, #{st09EquipCode}
			, SYSDATE
			, #{st09Empno}
			, #{st09Dept}
		)

mapper.select:
/** [sql-anomaly.xml] AnomalyMapper.comboDeptCodeList **/
SELECT CM03_CODE, CM03_NAME 
FROM TB_CM_03 CM03
WHERE 1=1
AND CM03.CM03_COMPANY = #{st09Company}
AND CM03.CM03_FACTORY = #{st09Factory}
AND CM03_LOCK = 'Y'
